const raw = $input.first().json;

// Facebook Lead Ads (simplified output) flattens field_data into top-level keys.
// Field keys vary per form, so probe common variants defensively.
function pick(obj, keys) {
  for (const k of keys) {
    const v = obj[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
}

const fullName = pick(raw, ['full_name', 'name', 'your_name']);
const firstName = pick(raw, ['first_name']);
const lastName = pick(raw, ['last_name']);
const name = fullName || [firstName, lastName].filter(Boolean).join(' ') || 'Unknown Lead';

const email = pick(raw, ['email', 'email_address', 'work_email']).toLowerCase();
let phone = pick(raw, ['phone_number', 'phone', 'mobile', 'whatsapp_number']);
phone = phone.replace(/[^\d+]/g, '');

const interestRaw = pick(raw, ['interest', 'i_am_interested_in', 'investment_type', 'what_are_you_looking_for', 'service', 'segment']).toLowerCase();
const budgetRaw = pick(raw, ['budget', 'investment_budget', 'budget_range']);
const cityRaw = pick(raw, ['city', 'location', 'preferred_location']);

// ---- LEAD SEGMENTATION (AUTO TAGGING) ----
const SEGMENTS = [
  { tag: 'Pool Investment',   keywords: ['pool', 'pooled', 'fund'] },
  { tag: 'Joint Venture',     keywords: ['joint', 'jv', 'partner'] },
  { tag: 'Off Plan',          keywords: ['off plan', 'offplan', 'off-plan', 'under construction'] },
  { tag: 'Plot Owner',        keywords: ['plot', 'land'] },
  { tag: 'Real Estate Agent', keywords: ['agent', 'broker', 'realtor'] },
];
let segment = 'Off Plan'; // fallback bucket
for (const s of SEGMENTS) {
  if (s.keywords.some(k => interestRaw.includes(k))) { segment = s.tag; break; }
}

// ---- AUTO ASSIGNMENT (per-segment owner desk) ----
// odooUserId 0 = not mapped yet; set real Odoo res.users IDs during setup to auto-assign salesperson.
const AGENT_BY_SEGMENT = {
  'Pool Investment':   { name: 'Pool Investment Desk', odooUserId: 0 },
  'Joint Venture':     { name: 'Joint Venture Desk',   odooUserId: 0 },
  'Off Plan':          { name: 'Off Plan Desk',        odooUserId: 0 },
  'Plot Owner':        { name: 'Plot Owner Desk',      odooUserId: 0 },
  'Real Estate Agent': { name: 'Partnerships Desk',    odooUserId: 0 },
};
const agent = AGENT_BY_SEGMENT[segment];

// ---- LEAD QUALIFICATION (scoring) ----
let score = 0;
if (email) score += 30;
if (phone) score += 30;
const budgetNum = parseFloat(budgetRaw.replace(/[^\d.]/g, '')) || 0;
if (budgetNum >= 100000) score += 25; else if (budgetNum > 0) score += 10;
if (cityRaw) score += 15;
let quality = 'cold';
if (score >= 70) quality = 'hot'; else if (score >= 45) quality = 'warm';

const firstNameOnly = name.split(' ')[0];

return [{ json: {
  name,
  firstName: firstNameOnly,
  email,
  phone,
  interest: interestRaw,
  budget: budgetRaw,
  city: cityRaw,
  segment,
  quality,
  score,
  assignedAgent: agent.name,
  assignedUserId: agent.odooUserId,
  leadId: raw.id || '',
  createdTime: raw.created_time || $now.toISO(),
  whatsappBody: 'Hi ' + firstNameOnly + '! Thanks for your interest in ' + segment + ' with Zenith Smart Group. Your specialist (' + agent.name + ') will reach out shortly. Reply here anytime with questions.',
  emailSubject: 'Welcome to Zenith Smart Group — ' + segment,
  emailBody: '<p>Hi ' + firstNameOnly + ',</p><p>Thank you for your interest in <b>' + segment + '</b>. Your dedicated specialist <b>' + agent.name + '</b> will contact you shortly.</p><p>Warm regards,<br/>Zenith Smart Group</p>',
}}];

